{"content": "# -*- coding: utf-8 -*-
"""汇总 lmeval_*.log 的组级结果为对比表"""
import re, glob, os, json

TASKS = ['ceval-valid', 'cmmlu', 'arc_easy', 'hellaswag', 'openbookqa', 'piqa', 'social_iqa']
results = {}
for log in glob.glob(r'C:\mmwork\eval_suite\results\lmeval_*.log'):
    tag = os.path.basename(log)[7:-4]
    text = open(log, encoding='utf-8', errors='ignore').read()
    r = {}
    for t in TASKS:
        # 行如 |task |ver|filter|shot|metric|→|val|±err|
        for m in re.finditer(r'^\|(' + re.escape(t) + r')\s*\|[^|]*\|[^|]*\|[^|]*\|(acc_norm|acc)\s*\|[^|]*\|\s*([\d.]+)\|\s*±?\s*\|?\s*([\d.]+)\|', text, re.M):
            metric, val = m.group(2), float(m.group(3))
            key = t if metric == 'acc' else f'{t}:norm'
            r.setdefault(key, val)
        # 组级行 (缩进式)
    for m in re.finditer(r'^\|\s*(' + '|'.join(re.escape(t) for t in TASKS) + r')\s*\|\s*\d+\s*\|[^|]*\|[^|]*\|(acc_norm|acc)\s*\|[^|]*\|\s*([\d.]+)\|\s*±?\s*\|?\s*([\d.]+)\|', text, re.M):
        pass
    results[tag] = r

# 组级行提取(带前导空格的 Groups 表)
for log in glob.glob(r'C:\mmwork\eval_suite\results\lmeval_*.log'):
    tag = os.path.basename(log)[7:-4]
    for line in open(log, encoding='utf-8', errors='ignore'):
        m = re.match(r'^\|\s*(ceval-valid|cmmlu)\s*\|\s*\d+\s*\|[^|]*\|[^|]*\|(acc_norm|acc)\s*\|[^|]*\|\s*([\d.]+)\|', line)
        if m:
            t, metric, val = m.group(1), m.group(2), float(m.group(3))
            results[tag][t if metric == 'acc' else f'{t}:norm'] = val

# 单任务行 (Tasks 表中 arc_easy 等)
for log in glob.glob(r'C:\mmwork\eval_suite\results\lmeval_*.log'):
    tag = os.path.basename(log)[7:-4]
    for line in open(log, encoding='utf-8', errors='ignore'):
        m = re.match(r'^\|\s*(arc_easy|hellaswag|openbookqa|piqa|social_iqa)\s*\|\s*\d+\s*\|[^|]*\|[^|]*\|(acc_norm|acc)\s*\|[^|]*\|\s*([\d.]+)\|', line)
        if m:
            t, metric, val = m.group(1), m.group(2), float(m.group(3))
            results[tag][t if metric == 'acc' else f'{t}:norm'] = val

order = ['ceval-valid', 'cmmlu', 'arc_easy', 'arc_easy:norm', 'hellaswag', 'hellaswag:norm',
         'openbookqa', 'openbookqa:norm', 'piqa', 'piqa:norm', 'social_iqa']
tags = ['user_sft', 'exam_v2', 'exam_v3', 'dpo', 'official_sft']
print(f"{'task':<18}" + ''.join(f'{t:>14}' for t in tags if t in results))
for t in order:
    row = f'{t:<18}'
    for tag in tags:
        v = results.get(tag, {}).get(t)
        row += f'{v*100:>13.2f} ' if v is not None else f'{"—":>14}'
    print(row)
json.dump(results, open(r'C:\mmwork\eval_suite\results\benchmark_summary.json', 'w'), indent=1)
print('\nsaved benchmark_summary.json')
