{"content": "# -*- coding: utf-8 -*-
"""步骤2: 分层选题(30 题 = v1 合成 20 + v2 真实照片 10), 复制图片, 输出选题清单与 v2 子集
运行: C:\\Users\\UserX\\.conda\\envs\\opencv\\python.exe prepare_selection.py
"""
import os, json, shutil, ast

RES = r'C:\Users\UserX\Downloads\minimind-v\eval_suite\results'
FB = r'C:\mmwork_v\eval_suite\results'
V2SRC = r'C:\mmwork_v\eval_suite\synbench_v2'
OUT = r'C:\mmwork\report30'
CATS = ['color', 'shape', 'count', 'pos', 'digit']

V1_MODELS = [('official', '官方原版'), ('user', '你的原版 VLM'), ('e1', 'E1 LoRA'),
             ('e2', 'E2 DoRA'), ('e3', 'E3 LoRA+'), ('e4', 'E4 Muon'),
             ('f1d', 'F1d'), ('f1e', 'F1e（交付）')]
V2_MODELS = [('official', '官方原版'), ('user', '你的原版 VLM'),
             ('f1d', 'F1d'), ('f1e', 'F1e（交付）')]


def load(name):
    for d in (RES, FB):
        p = os.path.join(d, name)
        if os.path.exists(p):
            return json.load(open(p, encoding='utf-8'))
    raise FileNotFoundError(name)


def clean_target(t):
    if isinstance(t, str) and t.startswith('['):
        try:
            v = ast.literal_eval(t)
            return '、'.join(map(str, v)) if isinstance(v, list) else str(v)
        except Exception:
            return t
    return str(t)


def main():
    os.makedirs(f'{OUT}/img/v2', exist_ok=True)
    v1 = {tag: {it['id']: it for it in load(f'synbench_{tag}.json')['items']} for tag, _ in V1_MODELS}
    v2 = {tag: {it['id']: it for it in load(f'synbench2_{tag}.json')['items']}
          for tag in ('official', 'f1d', 'f1e')}

    sel = {'v1': [], 'v2': []}
    # --- v1: 每类 4 题, 按"答对的模型数"分层取最难的/1/3位/2/3位/最易的 ---
    for cat in CATS:
        ids = [f'{cat}{i}' for i in range(80)]
        nc = {i: sum(1 for tag, _ in V1_MODELS if v1[tag][i]['hit']) for i in ids}
        order = sorted(ids, key=lambda i: (nc[i], int(i[len(cat):])))
        picks = [order[0], order[len(order) // 3], order[2 * len(order) // 3], order[-1]]
        for i in picks:
            sel['v1'].append({'id': i, 'q': v1['official'][i]['q'],
                              'target': clean_target(v1['official'][i]['target'])})
    # --- v2: 真实照片部分, 每类 2 题(优先"官方错/F1e 对", 再取全对), 题源用 mmwork_v 原图 ---
    v2items = {it['id']: it for it in json.load(open(f'{V2SRC}/items.json', encoding='utf-8'))}
    sub = []
    for cat in CATS:
        ids = [f'real_{cat}{j}' for j in range(100)]
        ids = [i for i in ids if i in v2['official']]
        pref = [i for i in ids if (not v2['official'][i]['hit']) and v2['f1e'][i]['hit']]
        allok = [i for i in ids if all(v2[t][i]['hit'] for t in ('official', 'f1d', 'f1e'))]
        pick1 = pref[0] if pref else ids[0]
        pick2 = (allok[0] if allok else ids[len(ids) // 2])
        for i in dict.fromkeys([pick1, pick2]):
            it = v2items[i]
            shutil.copy(os.path.join(V2SRC, it['img']), f'{OUT}/img/v2/{i}.png')
            sub.append(it)
            sel['v2'].append({'id': i, 'q': it['q'], 'target': clean_target(it['target'])})

    json.dump(sel, open(f'{OUT}/selection.json', 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
    json.dump(sub, open(f'{OUT}/v2sub_items.json', 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
    print('v1 选题:', [s['id'] for s in sel['v1']])
    print('v2 选题:', [s['id'] for s in sel['v2']])
    print('total', len(sel['v1']) + len(sel['v2']))


if __name__ == '__main__':
    main()
